const domain = $env.COMPANY_DOMAIN || 'example.com';
const baseUrl = `https://${domain}`;

const checks = [
  { type: 'robots_txt', url: `${baseUrl}/robots.txt`, description: 'Robots.txt' },
  { type: 'sitemap', url: `${baseUrl}/sitemap.xml`, description: 'Sitemap XML' },
  { type: 'sitemap_index', url: `${baseUrl}/sitemap_index.xml`, description: 'Sitemap Index' },
  { type: 'favicon', url: `${baseUrl}/favicon.ico`, description: 'Favicon' },
  { type: 'security_txt', url: `${baseUrl}/.well-known/security.txt`, description: 'Security.txt' }
];

return checks.map(c => ({ json: { ...c, domain, baseUrl } }));

const items = $input.all();
const results = [];
const issues = [];
let score = 100;

for (const item of items) {
  const response = item.json;
  const checkInfo = $node['Define Technical Checks'].json;
  const statusCode = response.statusCode || response.status || 0;
  const body = response.body || response.data || '';
  const bodyStr = typeof body === 'string' ? body : JSON.stringify(body);

  let checkResult = { type: checkInfo.type, url: checkInfo.url, status: 'pass', details: {} };

  switch (checkInfo.type) {
    case 'robots_txt':
      if (statusCode !== 200) {
        checkResult.status = 'fail';
        issues.push({ severity: 'high', message: 'robots.txt not found (404)', fix: 'Create a robots.txt file in your root directory' });
        score -= 15;
      } else {
        const hasDisallowAll = bodyStr.includes('Disallow: /');
        const hasSitemap = bodyStr.toLowerCase().includes('sitemap:');
        if (hasDisallowAll && !bodyStr.includes('Disallow: /admin')) {
          issues.push({ severity: 'critical', message: 'robots.txt blocks all crawling', fix: 'Review Disallow rules' });
          score -= 30;
        }
        if (!hasSitemap) {
          issues.push({ severity: 'medium', message: 'robots.txt missing Sitemap directive', fix: 'Add Sitemap: https://domain.com/sitemap.xml' });
          score -= 5;
        }
        checkResult.details = { has_sitemap_ref: hasSitemap, blocks_all: hasDisallowAll };
      }
      break;

    case 'sitemap':
    case 'sitemap_index':
      if (statusCode !== 200) {
        if (checkInfo.type === 'sitemap') {
          checkResult.status = 'fail';
          issues.push({ severity: 'high', message: 'sitemap.xml not found', fix: 'Generate and submit a sitemap' });
          score -= 15;
        }
      } else {
        const isXml = bodyStr.includes('<?xml') || bodyStr.includes('<urlset') || bodyStr.includes('<sitemapindex');
        if (!isXml) {
          issues.push({ severity: 'medium', message: 'Sitemap is not valid XML', fix: 'Ensure sitemap returns proper XML format' });
          score -= 10;
        }
        const urlCount = (bodyStr.match(/<loc>/g) || []).length;
        checkResult.details = { is_valid_xml: isXml, url_count: urlCount };
      }
      break;

    case 'favicon':
      if (statusCode !== 200) {
        checkResult.status = 'warning';
        issues.push({ severity: 'low', message: 'Favicon not found', fix: 'Add a favicon.ico to your root directory' });
        score -= 3;
      }
      break;
  }

  results.push(checkResult);
}

return [{
  json: {
    domain: $node['Define Technical Checks'].json.domain,
    audit_score: Math.max(0, score),
    total_checks: results.length,
    passed: results.filter(r => r.status === 'pass').length,
    failed: results.filter(r => r.status === 'fail').length,
    warnings: results.filter(r => r.status === 'warning').length,
    issues: issues,
    results: results,
    audited_at: new Date().toISOString()
  }
}];

parameters.text:
