*Checks:* {{ $json.passed }} passed | {{ $json.failed }} failed | {{ $json.warnings }} warnings

{{ $json.issues.length > 0 ? '*Issues Found:*\n' + $json.issues.map(i => `• [${i.severity.toUpperCase()}] ${i.message}\n  Fix: ${i.fix}`).join('\n') : '✅ No issues found!' }}
